-- XOR Swap Algorithm
-- This algorithm swaps two variables by using the XOR bitwise operator
-- on their values. It works by first XORing the first variable with
-- the second variable, storing the result in the first variable.
-- Then, it XORs the result in the first variable with the second variable,
-- and stores the result in the second variable. Finally, it XORs the result
-- in the second variable with the first variable, and stores the result in
-- the first variable. At the end of this process, the two variables have
-- been swapped.

with Ada.Text_IO; use Ada.Text_IO;

procedure Swap is
   -- Declare variables
   First_Value, Second_Value : Integer;

   -- Procedure to swap two variables using XOR
   procedure XOR_Swap (A, B : in out Integer) is
      C : Integer;
   begin
      C := A xor B;
      A := C xor A;
      B := C xor B;
   end XOR_Swap;

begin
   Put("Enter the first value: ");
   Get(First_Value);

   Put("Enter the second value: ");
   Get(Second_Value);

   Put("Before swapping: ");
   Put("First Value = ");
   Put(First_Value);
   New_Line;
   Put("Second Value = ");
   Put(Second_Value);
   New_Line;

   -- Call the swap procedure and swap the values
   XOR_Swap(First_Value, Second_Value);

   -- Display swapped values
   Put("After swapping: ");
   Put("First Value = ");
   Put(First_Value);
   New_Line;
   Put("Second Value = ");
   Put(Second_Value);
   New_Line;
end Swap;

